// 1. 获取 Gmail 节点返回的表单数据
const form = $input.first().json.data;

if (!form) {
  throw new Error("未找到表单数据，请检查 Gmail 节点输出。");
}

// 2. 精准提取新表单中的字段
const finalTitle = form['1. 最终敲定标题 (Title)'] || '未命名标题';
const finalThesis = form['2. 最终核心洞察 (Thesis)'] || '';
const finalArguments = form['3. 最终核心论据 (Key Arguments & Facts)'] || '';
const editorFeedback = form['4. 定向搜证补充 (如需AI再查某些数据，请填写)'] || '无附加要求';

// 3. 跨节点获取上游生成的 content_id (保持你的 Fallback 逻辑)
let contentId = "UNKNOWN";
try {
  contentId = $('Parse Narrative JSON').first().json.content_id;
  if (!contentId || contentId === "UNKNOWN") {
    contentId = $('Parse Selectionx').first().json.content_id;
  }
} catch (e) {}

// 4. 物理缝合 Markdown 大纲
const outlineContent = `> **核心洞察 (Thesis):**\n${finalThesis}\n\n### 核心论据 (Key Arguments)\n${finalArguments}`;

const selectedAngle = {
  title: finalTitle,
  outline: outlineContent
};

// 🚀 新增：获取当前时间，防止搜证 Agent 产生时间幻觉
const currentDate = new Date().toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: 'long', day: 'numeric' });

// 🚀 5. 构造极度硬核的定向搜证 Intent
const targetedIntent = editorFeedback && editorFeedback !== '无附加要求' 
  ? `【主编定向狙击】：${editorFeedback}。请全网深挖硬核数据与实锤证据。`
  : `【深度弹药补全】：针对《${finalTitle}》的核心论点，挖掘最新的开发者吐槽(Reddit/X)、竞品API真实定价或财报实锤，拒绝公关废话。`;

// 🚀 6. 重构 Triage Prompt：从“找背景”升级为“找弹药”
const triagePrompt = `<role>
你是一位隶属于顶级科技媒体的“王牌调查记者”。主编已经敲定了文章的大纲，你的任务绝不是去搜集泛泛的“行业背景”或“专家废话”，而是为这篇即将发布的爆款长文寻找最锋利的【增量弹药】。
</role>

<context>
- **当前系统时间**：${currentDate} (搜证时必须对齐最新时间线)
- **文章标题**：《${finalTitle}》
- **主编特殊指令**：${editorFeedback}
- **已有核心论点**：${finalThesis}
</context>

<objective>
**绝对不要重复大纲里已经有的信息！** 你需要全网搜索（特别是 GitHub, Reddit, X/Twitter, 财报, 开发者论坛, 法庭文件），寻找以下三类增量信息：
1. **硬核数据补全**：比如具体的算力成本数字、API定价变动、财报里的隐藏亏损。
2. **社区真实吃瓜**：开发者、KOL或业内人士的犀利吐槽、原话引用（必须带情绪和具体场景，如“我的4090跑爆了”）。
3. **事实交叉验证**：如果大纲里提到了某项技术或诉讼（如迪士尼版权案），去查一下最新的进展、判决结果或官方回应。
</objective>

<output_format>
请用 Markdown 输出一份【增量弹药库】，直接列出干货，不要任何过渡句：
### 1. 📊 最新硬核数据 (New Hard Facts)
-[时间戳] 具体数据或事实...

### 2. 🗣️ 社区与开发者原声 (Community Voices)
- [平台/人名] 原话引用...

### 3. 🔍 细节与进展补充 (Context & Updates)
- [时间戳] 最新进展...

*(注意：如果没有找到某类高质量信息，请直接写“无增量”，绝不脑补！)*
</output_format>`;

// 7. 构造完美的输出契约
return {
  json: {
    content_id: contentId,
    final_narrative: selectedAngle,
    editor_feedback: editorFeedback,
    topic_intent: targetedIntent,
    source_lane: "auto",
