// 辅助函数：更加宽容的标签提取逻辑
function extractTag(text, tag) {
  if (!text) return "";
  // 匹配 **标签**: 或者 **标签**： 甚至带括号的情况
  const regex = new RegExp(`\\*\\*${tag}[^*]*\\*\\*[:：]\\s*([\\s\\S]*?)(?=\\n\\*\\*|$)`, "i");
  const match = text.match(regex);
  return match ? match[1].trim() : "";
