// 1. 获取 Gemini 原生节点输出的纯文本字符串
// 兼容 n8n 各种文本输出路径
let rawText = $input.first().json.text || $input.first().json.message?.content || $input.first().json.content?.parts?.[0]?.text || "";

// 如果由于某些原因它已经是对象了，直接转回文本（极少发生）
if (typeof rawText !== 'string') {
    rawText = JSON.stringify(rawText);
}

// 2. 物理清洗（防范万一出现的 ```json 标签）
let cleanText = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. 解冻！将字符串反序列化为真实的 JSON 对象
let parsed = {};
try {
  parsed = JSON.parse(cleanText);
} catch (e) {
  throw new Error("JSON.parse 解析失败，请检查模型输出是否为合法 JSON。原始文本: " + cleanText);
}

// 4. 提取离散的结构化数据
const angleA = parsed.angle_1 || parsed.angle_a ||  {};
const angleB = parsed.angle_2 || parsed.angle_b || {};

// 5. 继承上游主键 (请确保这里写的是你上游保存上下文的节点名)
// 默认回退一个空对象防报错
let context = { content_id: "UNKNOWN" };
try {
    context = $('Brief Data Extraction').first().json;
} catch(e) {}

// 6. 华丽输出！现在下游可以直接用 $json.angle_a.title 引用了！
return {
  json: {
    content_id: context.content_id,
    angle_a: angleA,
    angle_b: angleB
  }
};

