  // 2. 提取大纲内容
  const title = final_narrative?.title || '未命名大纲';
  const outline = final_narrative?.outline || JSON.stringify(final_narrative);

  // 3. 终极物理缝合 (Markdown)
  const mergedContent = `${original_brief_text}\n\n---\n\n# 【主编敲定大纲】\n${title}\n\n${outline}\n\n---\n\n# 【定向增量情报】\n${suppText}`;

  // 4. 重新打包为 n8n Binary Data，准备覆盖原始文件
  item.binary = {
    data: await this.helpers.prepareBinaryData(
      Buffer.from(mergedContent, 'utf-8'),
      'updated_brief.md',
      'text/markdown'
    )
  };
}

return items;

// 1. 遍历并提取二进制文本
